#!/usr/bin/env node
/**
 * Long single-take drone fly-through via Veo 3.1 chained extension → public/hero/hero-veo-long.mp4.
 *
 * Veo 3.1: base clip = 8s, each extend = +7s (720p only), and the result is ONE continuous no-cut shot.
 * Chaining a SECOND extension immediately fails ("Input video must be a video that was generated by VEO
 * that has been processed") because the extended result needs server-side processing first. So we:
 *   1. base (8s) → extend #1 (+7s = 15s) and DOWNLOAD it immediately as the guaranteed deliverable
 *   2. best-effort: poll the ext#1 file until ACTIVE, then try extend #2 (+7s = 22s); on success, overwrite
 * Either way you get a clean continuous take (15s guaranteed, ~22s if the 2nd extend is accepted).
 *
 * Usage:  node --env-file=.env.local scripts/extend-hero-veo.mjs
 */
import { GoogleGenAI } from "@google/genai";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { stat, writeFile } from "node:fs/promises";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const OUT = join(ROOT, "public", "hero", "hero-veo-long.mp4");
const MODEL = process.env.VEO_MODEL || "veo-3.1-generate-preview";

const BASE = `A single continuous aerial drone shot, one unbroken take, absolutely no cuts. Glide out of a sun-drenched Tulum villa bedroom through open glass doors onto a balcony, sweep low and fast over white sand and glassy turquoise surf, then tilt upward and accelerate into a bright blue sky, pushing through a soft sunlit cloud, emerging high over a glittering Dubai skyline at golden hour and banking toward one warmly glowing penthouse window. Smooth cinematic FPV drone motion, photorealistic, warm editorial color grade, volumetric golden light, no text, no logos, no people.`;
const CONT1 = `Continue the exact same unbroken aerial drone shot with no cut, matching motion and grade: pull smoothly back from the penthouse window, bank away over the glittering dusk skyline, then descend toward a snow-dusted alpine ski resort glowing in pink alpenglow. Photorealistic, cinematic FPV motion, no text, no people.`;
const CONT2 = `Continue the exact same unbroken aerial drone shot with no cut, matching motion and grade: drift down past the ski slopes toward a cozy timber cottage with warm firelight in its windows, then rise gently over a sparkling night city skyline, easing as if arriving home. Photorealistic, cinematic FPV motion, warm color grade, no text, no people.`;

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function poll(ai, op, label) {
  let waited = 0;
  while (!op.done) {
    await sleep(10000); waited += 10;
    console.log(`  ${label}: generating (${waited}s)`);
    op = await ai.operations.getVideosOperation({ operation: op });
  }
  if (op.error) throw new Error(`${label}: ${JSON.stringify(op.error)}`);
  const v = op.response?.generatedVideos?.[0]?.video;
  if (!v) throw new Error(`${label}: no video — ${JSON.stringify(op.response).slice(0, 400)}`);
  console.log(`  ${label}: ✓`);
  return v;
}

async function download(ai, video, apiKey) {
  try { await ai.files.download({ file: video, downloadPath: OUT }); }
  catch (e) {
    const uri = video?.uri || video?.videoUri;
    if (!uri) throw e;
    const res = await fetch(uri, { headers: { "x-goog-api-key": apiKey } });
    if (!res.ok) throw new Error(`download ${res.status}`);
    await writeFile(OUT, Buffer.from(await res.arrayBuffer()));
  }
  const s = await stat(OUT);
  console.log(`  saved ${OUT} (${(s.size / 1e6).toFixed(2)} MB)`);
}

function fileName(video) {
  if (video?.name) return video.name.startsWith("files/") ? video.name : `files/${video.name}`;
  const m = (video?.uri || "").match(/files\/([^:/?]+)/);
  return m ? `files/${m[1]}` : null;
}

async function waitActive(ai, video) {
  const name = fileName(video);
  if (!name) { console.log("  (no file name on video object; waiting fixed 45s before extend #2)"); await sleep(45000); return; }
  for (let i = 0; i < 30; i++) {
    try { const f = await ai.files.get({ name }); console.log(`  ext#1 file ${name} state=${f.state}`); if (f.state === "ACTIVE") { await sleep(3000); return; } }
    catch (e) { console.log(`  files.get: ${e.message}`); }
    await sleep(5000);
  }
}

async function main() {
  const apiKey = process.env.GEMINI_API_KEY || process.env.GOOGLE_API_KEY;
  if (!apiKey) { console.error("Missing GEMINI_API_KEY"); process.exit(1); }
  const ai = new GoogleGenAI({ apiKey });

  console.log("Veo: base take (villa → beach → cloud → Dubai, 8s, 720p)…");
  let op = await ai.models.generateVideos({ model: MODEL, prompt: BASE, config: { aspectRatio: "16:9", resolution: "720p", durationSeconds: 8 } });
  let video = await poll(ai, op, "base");

  console.log("Veo: extend #1 (+7s — Dubai → ski resort) → 15s…");
  op = await ai.models.generateVideos({ model: MODEL, prompt: CONT1, video, config: { resolution: "720p", numberOfVideos: 1 } });
  video = await poll(ai, op, "ext1");
  await download(ai, video, apiKey); // guaranteed 15s deliverable
  console.log("✓ 15s single-take saved as the safe deliverable.");

  // best-effort upgrade to ~22s
  try {
    console.log("Veo: waiting for ext#1 to be processed, then extend #2 (+7s — cottage → night skyline) → ~22s…");
    await waitActive(ai, video);
    op = await ai.models.generateVideos({ model: MODEL, prompt: CONT2, video, config: { resolution: "720p", numberOfVideos: 1 } });
    video = await poll(ai, op, "ext2");
    await download(ai, video, apiKey);
    console.log("\n✓ ~22s single-take saved.");
  } catch (e) {
    console.log(`\nExtend #2 not accepted (${e.message?.slice(0, 160)}). Keeping the clean 15s take.`);
  }
}

main().catch((e) => { console.error("FAILED:", e?.message || e); process.exit(1); });
